"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ACCESS_STACK_2025,
  DESERT_RURAL_SPLIT,
  DUAL_METRIC_COMPARE,
  HEADLINE,
  NEWSPAPER_STRUCTURE,
  OUTLET_MIX_2025,
  PUBLIC_REACH,
  RISK_FUNNEL,
  SOURCE_NOTE,
  desertSeries,
  dualMetricBars,
  fmtInt,
  fmtM,
  fmtPct,
  statesByRegion,
  type AccessMetric,
  type RegionFilter,
} from "@/data/us-counties-with-no-local-news-outlet-2026-data";

// viz-types: desert area+line, state horizontal bars, risk funnel bars, public-reach composed, rural pie, density??owners scatter | layout: default

type ViewId = "deserts" | "states" | "risk" | "ecosystem";

const NAVY = "#0f172a";
const AMBER = "#d97706";
const TEAL = "#0f766e";
const ROSE = "#be123c";
const SLATE = "#64748b";
const INDIGO = "#4338ca";
const EMERALD = "#059669";

const REGION_OPTS: { id: RegionFilter; label: string }[] = [
  { id: "all", label: "All regions" },
  { id: "south", label: "South" },
  { id: "midwest", label: "Midwest" },
  { id: "west", label: "West" },
  { id: "northeast", label: "Northeast" },
];

const METRIC_OPTS: { id: AccessMetric; label: string }[] = [
  { id: "allOutlets", label: "All outlets (deserts)" },
  { id: "newspaperOnly", label: "Newspaper 0???1 pop" },
];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function UsCountiesWithNoLocalNewsOutlet2026Dashboard() {
  const [view, setView] = useState<ViewId>("deserts");
  const [metric, setMetric] = useState<AccessMetric>("allOutlets");
  const [region, setRegion] = useState<RegionFilter>("all");

  const path = useMemo(() => desertSeries(), []);
  const dual = useMemo(() => dualMetricBars(metric), [metric]);
  const states = useMemo(() => {
    const rows = statesByRegion(region)
      .map((s) => ({
        state: s.state,
        popM: s.limitedAccessPopM,
        share: s.limitedAccessSharePct,
        confidence: s.confidence,
      }))
      .sort((a, b) => b.popM - a.popM);
    return rows;
  }, [region]);

  const funnel = useMemo(
    () =>
      RISK_FUNNEL.map((r) => ({
        stage: r.stage.replace(" (>40% desert risk / 10y)", ""),
        counties: r.counties,
      })),
    [],
  );

  const reach = useMemo(
    () =>
      PUBLIC_REACH.map((p) => ({
        metric: p.metric,
        primary: p.primaryPct,
        repeaters: p.withRepeatersPct,
      })),
    [],
  );

  const ruralPie = useMemo(
    () =>
      DESERT_RURAL_SPLIT.map((d) => ({
        name: d.label,
        value: d.sharePct,
      })),
    [],
  );

  const stack = useMemo(
    () =>
      ACCESS_STACK_2025.map((a) => ({
        band: a.band,
        counties: a.counties,
      })),
    [],
  );

  const structureScatter = useMemo(
    () =>
      NEWSPAPER_STRUCTURE.map((n) => ({
        year: n.year,
        papersPer100k: n.papersPer100k,
        owners: n.uniqueOwners / 1000,
        circ: n.circulationM,
      })),
    [],
  );

  const outletMix = useMemo(
    () =>
      OUTLET_MIX_2025.map((o) => ({
        type: o.type.replace(" / foreign-language", ""),
        count: o.count,
      })),
    [],
  );

  return (
    <div
      className="space-y-6"
      data-viz="us-counties-with-no-local-news-outlet-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-6 text-white shadow-sm sm:px-8">
        <p className="text-xs font-semibold uppercase tracking-[0.14em] text-amber-300">
          Local information ?? Medill 2025
        </p>
        <h2 className="mt-2 text-2xl font-bold tracking-tight sm:text-3xl">
          Counties with 0???1 outlets
        </h2>
        <p className="mt-2 max-w-3xl text-sm text-slate-300 sm:text-base">
          Medill counts{" "}
          <span className="font-semibold text-white">
            {fmtInt(HEADLINE.zeroOutletCounties2025)}
          </span>{" "}
          U.S. counties with zero locally based news sources and{" "}
          <span className="font-semibold text-white">
            {fmtInt(HEADLINE.oneOutletCounties2025)}
          </span>{" "}
          with only one ??? roughly{" "}
          <span className="font-semibold text-amber-200">
            {fmtM(HEADLINE.limitedAccessPopM, 0)}
          </span>{" "}
          people with limited or no local news.
        </p>
        <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
          <div className="rounded-lg bg-white/5 px-3 py-2">
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              Zero-outlet
            </p>
            <p className="text-xl font-bold tabular-nums">
              {fmtInt(HEADLINE.zeroOutletCounties2025)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2">
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              One outlet
            </p>
            <p className="text-xl font-bold tabular-nums">
              {fmtInt(HEADLINE.oneOutletCounties2025)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2">
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              Watch list
            </p>
            <p className="text-xl font-bold tabular-nums">
              {fmtInt(HEADLINE.watchListCounties)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2">
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              Rural deserts
            </p>
            <p className="text-xl font-bold tabular-nums">
              {fmtPct(HEADLINE.ruralShareOfDesertsPct)}
            </p>
          </div>
        </div>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="Panel"
          value={view}
          options={[
            { id: "deserts", label: "Desert path" },
            { id: "states", label: "State exposure" },
            { id: "risk", label: "Risk funnel" },
            { id: "ecosystem", label: "Ecosystem" },
          ]}
          onChange={setView}
        />
        <div className="flex flex-wrap gap-3">
          <ToggleGroup
            label="Metric"
            value={metric}
            options={METRIC_OPTS}
            onChange={setMetric}
          />
          <ToggleGroup
            label="Region"
            value={region}
            options={REGION_OPTS}
            onChange={setRegion}
          />
        </div>
      </div>

      {view === "deserts" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Zero-outlet counties since 2005"
            subtitle="Medill disclosed annual points; mid-path estimated/carried"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={path}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                  <YAxis tick={{ fontSize: 12 }} />
                  <Tooltip />
                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="zero"
                    name="Zero outlets"
                    fill={ROSE}
                    fillOpacity={0.15}
                    stroke={ROSE}
                    strokeWidth={2}
                  />
                  <Line
                    type="monotone"
                    dataKey="limited"
                    name="0+1 (when known)"
                    stroke={AMBER}
                    strokeWidth={2}
                    strokeDasharray="4 4"
                    connectNulls={false}
                    dot={{ r: 3 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title={
              metric === "allOutlets"
                ? "Desert counties: 2005 vs 2025"
                : "People in 0???1 newspaper counties"
            }
            subtitle="Toggle Metric control above"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={dual}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                  <YAxis tick={{ fontSize: 12 }} />
                  <Tooltip />
                  <Bar dataKey="value" name={dual[0]?.label ?? "Value"} radius={[6, 6, 0, 0]}>
                    {dual.map((_, i) => (
                      <Cell key={i} fill={i === 0 ? SLATE : ROSE} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="2025 county access stack"
            subtitle="Share of 3,144 U.S. counties by outlet count"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={stack} layout="vertical" margin={{ left: 24 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 12 }} />
                  <YAxis
                    type="category"
                    dataKey="band"
                    width={120}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip />
                  <Bar dataKey="counties" name="Counties" radius={[0, 6, 6, 0]}>
                    {stack.map((_, i) => (
                      <Cell
                        key={i}
                        fill={[ROSE, AMBER, TEAL][i] ?? NAVY}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Deserts are mostly rural"
            subtitle="USDA predominantly rural share of zero-outlet counties"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={ruralPie}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={95}
                    paddingAngle={3}
                    label={({ name, value }) => `${name}: ${value}%`}
                  >
                    {ruralPie.map((_, i) => (
                      <Cell key={i} fill={i === 0 ? AMBER : INDIGO} />
                    ))}
                  </Pie>
