"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ACCESS_STACK_2025,
  DESERT_RURAL_SPLIT,
  DUAL_METRIC_COMPARE,
  HEADLINE,
  NEWSPAPER_STRUCTURE,
  OUTLET_MIX_2025,
  PUBLIC_REACH,
  RISK_FUNNEL,
  SOURCE_NOTE,
  desertSeries,
  dualMetricBars,
  fmtInt,
  fmtM,
  fmtPct,
  statesByRegion,
  type AccessMetric,
  type RegionFilter,
} from "@/data/us-counties-with-no-local-news-outlet-2026-data";

// viz-types: desert area+line, state horizontal bars, risk funnel bars, public-reach composed, rural pie, density??owners scatter | layout: default

type ViewId = "deserts" | "states" | "risk" | "ecosystem";

const NAVY = "#0f172a";
const AMBER = "#d97706";
const TEAL = "#0f766e";
const ROSE = "#be123c";
const SLATE = "#64748b";
const INDIGO = "#4338ca";
const EMERALD = "#059669";

const REGION_OPTS: { id: RegionFilter; label: string }[] = [
  { id: "all", label: "All regions" },
  { id: "south", label: "South" },
  { id: "midwest", label: "Midwest" },
  { id: "west", label: "West" },
  { id: "northeast", label: "Northeast" },
];

const METRIC_OPTS: { id: AccessMetric; label: string }[] = [
  { id: "allOutlets", label: "All outlets (deserts)" },
  { id: "newspaperOnly", label: "Newspaper 0???1 pop" },
];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function UsCountiesWithNoLocalNewsOutlet2026Dashboard() {
  const [view, setView] = useState<ViewId>("deserts");
  const [metric, setMetric] = useState<AccessMetric>("allOutlets");
  const [region, setRegion] = useState<RegionFilter>("all");

  const path = useMemo(() => desertSeries(), []);
  const dual = useMemo(() => dualMetricBars(metric), [metric]);
  const states = useMemo(() => {
    const rows = statesByRegion(region)
      .map((s) => ({
        state: s.state,
        popM: s.limitedAccessPopM,
        share: s.limitedAccessSharePct,
        confidence: s.confidence,
      }))
      .sort((a, b) => b.popM - a.popM);
    return rows;
  }, [region]);

  const funnel = useMemo(
    () =>
      RISK_FUNNEL.map((r) => ({
        stage: r.stage.replace(" (>40% desert risk / 10y)", ""),
        counties: r.counties,
      })),
    [],
  );

  const reach = useMemo(
    () =>
      PUBLIC_REACH.map((p) => ({
        metric: p.metric,
        primary: p.primaryPct,
        repeaters: p.withRepeatersPct,
      })),
    [],
  );

  const ruralPie = useMemo(
    () =>
      DESERT_RURAL_SPLIT.map((d) => ({
        name: d.label,
