            <p className="text-xl font-bold tabular-nums">
              {fmtInt(HEADLINE.zeroOutletCounties2025)}
            </p>
          </div>
          <div className="rounded-lg bg-white/5 px-3 py-2">
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              One outlet
            </p>
            <p className="text-xl font-bold tabular-nums">
