              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "ecosystem" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Local news outlet mix (2025)"
            subtitle="~8,000 outlets in Medill???s census"
