                    }
                    labelFormatter={(_, payload) => {
                      const p = payload?.[0]?.payload as
                        | { year?: number }
                        | undefined;
                      return p?.year ? `Year ${p.year}` : "";
                    }}
                  />
                  <Scatter name="Structure" data={structureScatter} fill={ROSE} />
