                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Dual twenty-year comparison"
            subtitle="Medill disclosed endpoints for deserts, newspaper access, density, owners"
          >
            <div className="h-[28rem] w-full min-w-0">
