          onChange={setView}
        />
        <div className="flex flex-wrap gap-3">
          <ToggleGroup
            label="Metric"
            value={metric}
            options={[
              { id: "allOutlets", label: "All outlets" },
              { id: "newspaperOnly", label: "Newspaper 0???1" },
            ]}
            onChange={setMetric}
          />
          <ToggleGroup
            label="Region"
            value={region}
            options={[
              { id: "all", label: "All" },
              { id: "south", label: "South" },
              { id: "midwest", label: "Midwest" },
              { id: "west", label: "West" },
              { id: "northeast", label: "Northeast" },
            ]}
