                    name="Zero outlets"
                    fill={ROSE}
                    fillOpacity={0.15}
                    stroke={ROSE}
                    strokeWidth={2}
                  />
                  <Line
                    type="monotone"
                    dataKey="limited"
                    name="0+1 (when known)"
                    stroke={AMBER}
                    strokeWidth={2}
                    strokeDasharray="4 4"
                    connectNulls={false}
                    dot={{ r: 3 }}
